push.css:
.fxs .cs{--pushA:#4E9A4A;--pushB:#164D26;--pushC:#86CC72;--rim:#FFFFFF;--rimD:#164D26}
.fxs .push.cs{--pr:50px;border-radius:50px;background:#4E9A4A;box-shadow:0 0 0 3px #FFFFFF,0 7px 0 3px #164D26,0 20px 28px rgba(0,30,0,.4)}
.fxs .push.cs span{font:400 42px/1 "Train One",sans-serif;letter-spacing:.06em;color:#FFFFFF;text-shadow:0 2px 0 #164D26,0 0 10px rgba(255,255,255,.4)}
.fxs .push.cs::after{border-radius:70px;border-color:rgba(255,255,255,.9)}
.fxs .cs .csf{position:absolute;left:0;top:0;width:200px;height:100px;border-radius:50px;overflow:hidden;pointer-events:none;font-style:normal}
.fxs .cs .csf svg{display:block;width:200px;height:100px}
.fxs .cs .csd{position:absolute;left:0;top:0;width:200px;height:100px;pointer-events:none;z-index:3;font-style:normal}
.fxs .cs .csrun{position:absolute;left:0;top:0;width:39px;height:21px;animation:fxcsRun 5.4s linear infinite}
.fxs .cs .csrun>i{display:block;width:39px;height:21px;background-size:78px 21px;background-repeat:no-repeat;animation:fxcsPg .26s steps(1) infinite}
.fxs .cs .csrun.r1{animation-delay:-1.8s}
.fxs .cs .csrun.r2{animation-delay:-3.6s}
@keyframes fxcsPg{0%{background-position:0 0}50%{background-position:-39px 0}100%{background-position:0 0}}
.fxs .pshadow.cs{width:210px}
.fxs .tap.cs{font-family:"Train One",sans-serif;font-weight:400;color:#E9F8E2;letter-spacing:.12em;text-shadow:0 2px 0 #164D26,0 0 10px rgba(255,255,255,.5)}
.fxs .pressed.cs{border-radius:50px;background:#4E9A4A;box-shadow:0 0 0 3px #FFFFFF,0 7px 0 3px #164D26;animation-name:fxcsPress,fxfxH}
@keyframes fxcsPress{0%{transform:scale(1)}22%{transform:scale(.92)}45%{transform:scale(1.06)}100%{transform:scale(1.45);opacity:0}}
@media (prefers-reduced-motion:reduce){.fxs .cs .csrun,.fxs .cs .csrun>i{animation:none}
.fxs .cs .csd,.fxs .clips.cs{display:none}}
